 * A standalone, client-side router path matcher in the spirit of React Router.
 *
 * Pattern syntax:
 *   /users            static segment
 *   /users/:id        dynamic param segment
 *   /docs/:lang?      optional param segment (trailing `?`)
 *   /files/*          splat: matches everything under /files (may be empty)
 *
 * compile(pattern) returns a matcher function:
 *   matcher(pathname) -> { params, splat } | null
 *
 * rank(patterns, pathname) picks the most specific pattern, mirroring
 * React Router's ranking: each pattern gets a score where
 *   - static segments score highest,
 *   - dynamic params score lower,
 *   - splats score lowest,
 *   - deeper (longer) patterns break ties upward.
 */

// --- Types -----------------------------------------------------------------

export interface MatchResult {
  /** Named params extracted from `:param` segments (percent-decoded). */
  params: Record<string, string>;
  /** The remainder matched by a trailing `*` splat (percent-decoded), or null. */
  splat: string | null;
}

export type Matcher = (pathname: string) => MatchResult | null;

interface CompiledPattern {
  /** Original pattern as given. */
  pattern: string;
  /** Segment descriptors after normalization. */
  segments: Segment[];
  /** Whether the pattern ends with a splat. */
  hasSplat: boolean;
}

type Segment =
  | { kind: "static"; value: string }
  | { kind: "param"; name: string; optional: boolean }
  | { kind: "splat" };

// --- Normalization ----------------------------------------------------------

/**
 * Normalize a pattern or pathname: ensure leading slash, collapse duplicate
 * slashes, and drop a single trailing slash so `/foo/` and `/foo` match alike.
 */
export function normalize(path: string): string {
  let p = path;
  if (!p.startsWith("/")) p = "/" + p;
  // Collapse repeated slashes.
  p = p.replace(/\/{2,}/g, "/");
  // Drop trailing slash (but keep root "/").
  if (p.length > 1 && p.endsWith("/")) p = p.slice(0, -1);
  return p;
}

// --- Compilation ------------------------------------------------------------

/** Parse one raw segment (between slashes) into a descriptor. */
function parseSegment(raw: string): Segment {
  if (raw === "*") return { kind: "splat" };

  let optional = false;
  let name = raw;
  if (name.endsWith("?") && name.startsWith(":")) {
    optional = true;
    name = name.slice(0, -1);
  }
  if (name.startsWith(":")) {
    return { kind: "param", name: name.slice(1), optional };
  }
  // Static segment may itself carry a trailing `?` only when it's not a param;
  // React Router treats `?` on non-params as literal, but for ergonomics we
  // support optional statics too: e.g. `/about?` matches `/about` and `/`.
  if (raw.endsWith("?")) {
    return { kind: "static", value: raw.slice(0, -1) + "?" };
  }
  return { kind: "static", value: raw };
}

function compile(pattern: string): CompiledPattern {
  const normalized = normalize(pattern);
  const rawSegments = normalized.split("/").slice(1); // drop empty first element

  const segments: Segment[] = [];
  let hasSplat = false;

  for (const raw of rawSegments) {
    const seg = parseSegment(raw);
    segments.push(seg);
    if (seg.kind === "splat") hasSplat = true;
  }

  return { pattern, segments, hasSplat };
}

/**
 * Compile a route pattern and return a matcher over pathnames.
 * Throws on obviously invalid patterns (empty param name, misplaced splat).
 */
export function matcher(pattern: string): Matcher {
  const compiled = compile(pattern);

  // Validate early so authors get errors at route-definition time.
  compiled.segments.forEach((seg, i) => {
    if (seg.kind === "param" && seg.name === "") {
      throw new Error(`Invalid pattern "${pattern}": empty param name at segment ${i}`);
    }
    if (seg.kind === "splat" && i !== compiled.segments.length - 1) {
      throw new Error(`Invalid pattern "${pattern}": "*" is only allowed as the last segment`);
    }
    if (seg.kind === "param" && seg.optional && i !== compiled.segments.length - 1) {
      throw new Error(
        `Invalid pattern "${pattern}": optional segment ":${seg.name}?" must be the last segment`
      );
    }
  });

  return (pathname: string): MatchResult | null => {
    const normPath = normalize(pathname);
    const pathSegments = normPath === "/" ? [] : normPath.split("/").slice(1);

    const params: Record<string, string> = {};
    let splat: string[] | null = null;

    let pi = 0; // index into pathSegments

    for (let si = 0; si < compiled.segments.length; si++) {
      const seg = compiled.segments[si];
      const last = si === compiled.segments.length - 1;

      if (seg.kind === "splat") {
        // Splat greedily takes all remaining segments (possibly zero).
        splat = pathSegments.slice(pi).map(decodeSafe);
        pi = pathSegments.length;
        continue;
      }

      const available = pathSegments[pi];

      if (available !== undefined) {
        if (seg.kind === "static") {
          if (available !== seg.value) {
            // Static mismatch. As a nicety we tolerate an encoded form too.
            if (decodeSafe(available) !== seg.value) return null;
          }
          pi++;
          continue;
        }
        // param
        params[seg.name] = decodeSafe(available);
        pi++;
        continue;
      }

      // No more path segments left.
      if (seg.kind === "param" && seg.optional) {
        // Optional param absent: fine, but don't record it.
        continue;
      }
      return null;
    }

    // All pattern segments consumed; leftover path means no match — unless the
    // pattern ended with a splat, which already consumed everything.
    if (pi < pathSegments.length) return null;

    return {
      params,
      splat: splat === null ? null : splat.join("/"),
    };
  };
}

// --- Decoding ---------------------------------------------------------------

/** Decode a percent-encoded segment without throwing on malformed input. */
export function decodeSafe(value: string): string {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

// --- Ranking ------------------------------------------------------------------

/**
 * Score a compiled pattern against nothing but its own shape, mirroring
 * React Router's approach: compare segment by segment from index 0 while both
 * patterns have comparable segments; the first difference decides.
 *
 * We instead use a simpler additive score that produces the same ordering for
 * realistic route tables:
 *   static segment  : +10 per character-ish weight (we use +100 flat)
 *   dynamic segment : +10
 *   splat           : +1 (and penalized further by shallowness)
 *
 * To honor "static beats param beats splat" even across different lengths, we
 * compute a tuple score [indexOfFirstDifferenceKind, depth] lexicographically,
 * exactly like React Router's `compareIndexes` on segment kinds.
 */

const SCORE_STATIC = 100;
const SCORE_DYNAMIC = 10;
const SCORE_SPLAT = 1;

export interface Rankable {
  /** Route pattern string, e.g. "/users/:id". */
  pattern: string;
}

/**
 * Compute a sortable score for a pattern. Higher = more specific.
 * Returned as an array so array comparison yields lexicographic ordering.
 */
function scorePattern(pattern: string): number[] {
  const compiled = compile(pattern);
  const scores: number[] = [];

  compiled.segments.forEach((seg, i) => {
    switch (seg.kind) {
      case "static":
        scores[i] = (scores[i] ?? 0) + SCORE_STATIC + seg.value.length;
        break;
      case "param":
        scores[i] = (scores[i] ?? 0) + SCORE_DYNAMIC;
        break;
      case "splat":
        scores[i] = (scores[i] ?? 0) + SCORE_SPLAT;
        break;
    }
  });

  // Deeper routes are strictly more specific than shallower ones with equal
  // prefixes, so pad with a small depth bonus at the end.
  scores.push(compiled.segments.length);

  // A splat anywhere caps the tail: anything after comparing stops mattering.
  // (Handled naturally because splat scores lowest.)
  return scores;
}

function compareScores(a: number[], b: number[]): number {
  const len = Math.max(a.length, b.length);
  for (let i = 0; i < len; i++) {
    const ai = a[i] ?? 0;
    const bi = b[i] ?? 0;
    if (ai !== bi) return ai - bi;
  }
  return 0;
}

/**
 * Given a list of patterns and a pathname, pick the most specific matching
 * pattern using React Router-style ranking:
 *   - every segment kind ranks: static > dynamic > splat
 *   - among equals, longer (deeper) patterns win
 *   - ties fall back to the order given (stable)
 */
export function rank<T extends Rankable>(
  patterns: T[],
  pathname: string
): { match: T; params: Record<string, string>; splat: string | null } | null {
  let best: { match: T; result: MatchResult; score: number[] } | null = null;

  for (const entry of patterns) {
    const m = matcher(entry.pattern)(pathname);
    if (!m) continue;
    const score = scorePattern(entry.pattern);
    if (best === null || compareScores(score, best.score) > 0) {
      best = { match: entry, result: m, score };
    }
  }

  if (!best) return null;
  return {
    match: best.match,
    params: best.result.params,
    splat: best.result.splat,
  };
}
"})
