result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/router-match/test/matcher.test.ts", "content": "import { describe, expect, it } from "vitest";
import { matcher, rank, decodeSafe, normalize } from "../src/matcher.js";

// --- Static segments ---------------------------------------------------------

describe("static segments", () => {
  it.each([
    ["/", "/", {}],
    ["/about", "/about", {}],
    ["/a/b/c", "/a/b/c", {}],
    ["/about", "/aboutx", null],
    ["/about", "/abou", null],
    ["/about/team", "/about/team", {}],
    ["/about/team", "/about/other", null],
  ])("matcher(%j)(%j) -> %j", (pattern, path, expected) => {
    expect(matcher(pattern as string)(path as string)).toEqual(expected);
  });
});

// --- Dynamic params -----------------------------------------------------------

describe(":params", () => {
  it.each([
    ["/users/:id", "/users/42", { id: "42" }],
    ["/users/:id/posts/:postId", "/users/1/posts/9", { id: "1", postId: "9" }],
    ["/users/:id", "/users/a/b", null],
    ["/users/:id", "/users", null],
    ["/:lang/docs", "/en/docs", { lang: "en" }],
    ["/:lang/docs", "/docs", null],
  ])("matcher(%j)(%j)", (pattern, path, params) => {
    const m = matcher(pattern as string)(path as string);
    if (params === null) {
      expect(m).toBeNull();
    } else {
      expect(m).not.toBeNull();
      expect(m!.params).toEqual(params);
      expect(m!.splat).toBeNull();
    }
  });

  it("repeated param names keep the last value (like React Router)", () => {
    // Not a common pattern but shouldn't crash.
    const m = matcher("/:x/a/:x")("/1/a/2");
    expect(m?.params).toEqual({ x: "2" });
  });
});

// --- Optional segments ----------------------------------------------------------

describe("optional segments (:name?)", () => {
  it.each([
    ["/docs/:lang?", "/docs/en", { lang: "en" }],
    ["/docs/:lang?", "/docs", {}],
    ["/docs/:lang?", "/docs/en/more", null],
    ["/a/:b?/c", "/a/c", null], // optional must be last
  ])("matcher(%j)(%j)", (pattern, path, params) => {
    const m = matcher(pattern as string)(path as string);
    if (params === null) {
      // /a/:b?/c is rejected at compile time instead of matching.
      expect(() => matcher(pattern as string)).toThrow();
    } else {
      expect(m).not.toBeNull();
      expect(m!.params).toEqual(params);
    }
  });
});

// --- Splat -----------------------------------------------------------------------

describe("* splat", () => {
  it.each([
    ["/files/*", "/files/a/b/c.txt", "a/b/c.txt"],
    ["/files/*", "/files", ""], // splat can match empty remainder
    ["/files/*", "/files/", ""],
    ["/files/*", "/other", null],
    ["*", "/anything/at/all", "anything/at/all"],
    ["*", "/", ""],
    ["/a/*/b", "/a/x/y/b", null], // splat only allowed last
  ])("matcher(%j)(%j) splat=%j", (pattern, path, splat) => {
    const m = matcher(pattern as string)(path as string);
    if (splat === null && pattern !== "/a/*/b") {
      expect(m).toBeNull();
      return;
    }
    if (pattern === "/a/*/b") {
      expect(() => matcher(pattern as string)).toThrow();
      return;
    }
    expect(m).not.toBeNull();
    expect(m!.splat).toBe(splat);
  });

  it("percent-decodes the splat", () => {
    expect(matcher("/f/*")("/f/a%20b/c%d")).toMatchObject({ splat: "a b/c%d" });
  });
});

// --- Percent decoding ---------------------------------------------------------------

describe("percent-encoded params", () => {
  it.each([
    ["/users/:name", "/users/John%20Doe", "John Doe"],
    ["/q/:term", "/q/caf%C3%A9", "café"],
    ["/p/%2Fslash", "/p/%2Fslash", "/slash"],
  ])("%j matches %j -> %j", (pattern, path, decoded) => {
    expect(matcher(pattern as string)(path as string)?.params).toMatchObject({
      [Object.keys(matcher(pattern as string)("")).params ? "" : pattern.split("/:")[1]?.split("/")[0] ?? ""]: decoded,
    });
  });

  it.each([
    ["/x/%E0%A4%A", "/x/%E0%A4%A"], // truncated escape
    ["/x/%ZZ", "/x/%ZZ"], // invalid hex
    ["/x/%", "/x/%"], // bare percent
  ])("malformed encoding %j does not throw and returns raw value", (pattern, path) => {
    let m: ReturnType<ReturnType<typeof matcher>> | null = null;
    expect(() => {
      m = matcher(pattern)(path);
    }).not.toThrow();
    expect(m).not.toBeNull();
    expect(m!.params).toEqual({});
  });

  it("decodeSafe falls back to the raw value on malformed input", () => {
    expect(decodeSafe("%E0%A4%A")).toBe("%E0%A4%A");
    expect(decodeSafe("ok")).toBe("ok");
  });
});

// --- Trailing slash tolerance --------------------------------------------------------

describe("trailing-slash tolerance", () => {
  it.each([
    ["/about", "/about/"],
    ["/about", "/about"],
    ["/users/:id", "/users/7/"],
    ["/files/*", "/files/a/"],
    ["/", "/"],
  ])("matcher(%j)(%j) matches", (pattern, path) => {
    expect(matcher(pattern)(path)).not.toBeNull();
  });

  it("normalizes duplicate slashes", () => {
    expect(normalize("//a///b/")).toBe("/a/b");
    expect(matcher("/a/b")("//a//b")).not.toBeNull();
  });
});

// --- Ranking ----------------------------------------------------------------------

describe("rank", () => {
  it("prefers static over param", () => {
    const result = rank(
      [{ pattern: "/users/new" }, { pattern: "/users/:id" }],
      "/users/new"
    );
    expect(result?.match.pattern).toBe("/users/new");
  });

  it("prefers param over splat", () => {
    const result = rank(
      [{ pattern: "/*" }, { pattern: "/users/:id" }],
      "/users/42"
    );
    expect(result?.match.pattern).toBe("/users/:id");
  });

  it("prefers static over splat", () => {
    const result = rank([{ pattern: "/*" }, { pattern: "/home" }], "/home");
    expect(result?.match.pattern).toBe("/home");
  });

  it("longer beats shorter among equal kinds", () => {
    const result = rank(
      [{ pattern: "/users/:id" }, { pattern: "/users/:id/posts/:postId" }],
      "/users/1/posts/2"
    );
    expect(result?.match.pattern).toBe("/users/:id/posts/:postId");
  });

  it("static prefix beats shorter static", () => {
    const result = rank(
      [{ pattern: "/about" }, { pattern: "/about/team" }],
      "/about/team"
    );
    expect(result?.match.pattern).toBe("/about/team");
  });

  it("mixed specificity: /users/new beats /users/:id beats /*", () => {
    const patterns = [
      { pattern: "/*" },
      { pattern: "/users/:id" },
      { pattern: "/users/new" },
    ];
    expect(rank(patterns, "/users/new")?.match.pattern).toBe("/users/new");
    expect(rank(patterns, "/users/5")?.match.pattern).toBe("/users/:id");
    expect(rank(patterns, "/zzz")?.match.pattern).toBe("/*");
    expect(rank(patterns, "/zzz")?.splat).toBe("zzz");
  });

  it("returns null when nothing matches", () => {
    expect(rank([{ pattern: "/a" }, { pattern: "/b" }], "/c")).toBeNull();
  });

  it("ties fall back to first-listed (stable order)", () => {
    const patterns = [
      { name: "first", pattern: "/dup" },
      { name: "second", pattern: "/dup" },
    ];
    expect(rank(patterns, "/dup")?.match.name).toBe("first");
  });

  it("carries params through rank", () => {
    const result = rank(
      [{ pattern: "/users/:id" }, { pattern: "/*" }],
      "/users/99"
    );
    expect(result?.params).toEqual({ id: "99" });
    expect(result?.splat).toBeNull();
  });
});

// --- Compile-time validation ---------------------------------------------------------

describe("invalid patterns throw at compile time", () => {
  it.each([
    "/users/:",
    "/a/*/b",
    "/a/:x?/y",
  ])("%j throws", (pattern) => {
    expect(() => matcher(pattern)).toThrow();
  });
});
"})
